assignments.value:
={{ (() => {
  const fr = $('Typeform Trigger').first().json.form_response || {};
  const byRef = {};
  for (const a of (fr.answers || [])) {
    const raw = a[a.type];
    let v = raw;
    if (a.type === 'choice') v = raw?.label ?? raw?.other ?? '';
    else if (a.type === 'choices') v = [...(raw?.labels || []), ...(raw?.other ? [raw.other] : [])].join(', ');
    else if (a.type === 'payment') v = raw?.amount ?? '';
    else if (raw !== null && typeof raw === 'object') v = JSON.stringify(raw);
    byRef[a.field?.ref || a.field?.id] = v;
  }
  const s = v => (v === undefined || v === null) ? '' : String(v).trim();
  const hidden = fr.hidden || {};
  return {
    response_id: s(fr.token),
    submitted_at: s(fr.submitted_at) || $now.toISO(),
    form_id: s(fr.form_id),
    full_name: s(byRef.full_name),
    email: s(byRef.email).toLowerCase(),
    company: s(byRef.company),
    inquiry_type: s(byRef.inquiry_type),
    team_size: s(byRef.team_size),
    budget: s(byRef.budget),
    details: s(byRef.details).slice(0, 5000),
    utm_source: s(hidden.utm_source),
    unmapped_refs: Object.keys(byRef).filter(k => !['full_name', 'email', 'company', 'inquiry_type', 'team_size', 'budget', 'details'].includes(k))
  };
})() }}

={{ (() => {
  const t = String($json.submission?.inquiry_type ?? '').toLowerCase();
  if (/sales|demo|pricing|quote|buy|purchase/.test(t)) return 'sales';
  if (/support|help|bug|issue|problem|technical/.test(t)) return 'support';
  if (/partner|reseller|affiliate|agency/.test(t)) return 'partnership';
  return 'default';
})() }}

={{ (() => {
  const t = String($json.submission?.inquiry_type ?? '').toLowerCase();
  const nums = String($json.submission?.team_size ?? '').match(/\d+/g) || [];
  const size = nums.length ? Number(nums[nums.length - 1]) : 0;
  return /sales|demo|pricing|quote|buy|purchase/.test(t) && size >= $('Config · Routing Rules').first().json.hot_team_size ? 'HOT' : 'NORMAL';
})() }}

={{ (() => {
  const sub = $('Map Typeform Answers').first().json.submission;
  const pick = $('Pick Route & Priority').first().json;
  const cfg = $('Config · Routing Rules').first().json;
  const route = cfg.routing[pick.route_key] ?? cfg.routing.default;
  const saved = $json.airtable_saved !== false;
  const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const cut = (v, n) => { const t = esc(v); return t.length > n ? t.slice(0, n - 1) + '…' : t; };
  const recordUrl = saved && $json.id ? 'https://airtable.com/' + cfg.airtable_base_id + '/' + cfg.airtable_table_id + '/' + $json.id : '';

  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: (pick.priority === 'HOT' ? '🔥 ' : '🆕 ') + 'New ' + route.label + ' inquiry: ' + String(sub.full_name || 'Unknown').slice(0, 80), emoji: true } },
    { type: 'section', text: { type: 'mrkdwn', text: '<@' + route.owner_slack_id + '> this one is yours. *Priority:* ' + (pick.priority === 'HOT' ? '🔥 HOT' : 'Normal') } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: '*Name*\n' + cut(sub.full_name || '-', 200) },
      { type: 'mrkdwn', text: '*Email*\n<mailto:' + sub.email + '|' + cut(sub.email, 200) + '>' },
      { type: 'mrkdwn', text: '*Company*\n' + cut(sub.company || '-', 200) },
      { type: 'mrkdwn', text: '*Inquiry type*\n' + cut(sub.inquiry_type || '-', 200) },
      { type: 'mrkdwn', text: '*Team size*\n' + cut(sub.team_size || '-', 100) },
      { type: 'mrkdwn', text: '*Budget*\n' + cut(sub.budget || '-', 100) }
    ] },
    { type: 'section', text: { type: 'mrkdwn', text: '*Details*\n' + (cut(sub.details, 2800) || '_none_') } },
    { type: 'context', elements: [ { type: 'mrkdwn', text: 'Submitted ' + sub.submitted_at + ' · Response `' + sub.response_id + '`' + (sub.utm_source ? ' · Source ' + esc(sub.utm_source) : '') } ] }
  ];
  if (recordUrl) {
    blocks.push({ type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: 'Open in Airtable' }, url: recordUrl, style: 'primary' } ] });
  } else {
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':warning: *NOT saved to Airtable* (' + cut($json.airtable_error || 'unknown error', 200) + '). This message is the only copy; the team has been alerted by email.' } });
  }
  return blocks;
})() }}

={{ (() => {
  const t = $('On Workflow Error').first().json;
  const msg = t.execution?.error?.message ?? t.trigger?.error?.message ?? '';
  if (msg.includes('[CRITICAL]')) return 'CRITICAL';
  if (msg.includes('[WARNING]')) return 'WARNING';
  return 'ERROR';
})() }}

